/// <summary>
/// CB223_PalletRounding
/// The <c>METPalletRoundingPolicySearch</c> main class is inspired from PriceDiscPriceAgreementSearch and responsible for the pallet rounding policy search
/// </summary>
class METPalletRoundingPolicySearch
{
    const str CacheScopeFindPalletRoundingPolicy = METConstants::CacheScopeFindPalletRoundingPolicy;

    METPalletRoundingPolicySearchParameters palletRoundingPolicySearchParameters;
    METPalletRoundingPolicyLine             palletRoundingPolicyLine;

    METCustOperGroupId                      custOperGroupId;
    container                               cacheValue;
    boolean                                 cacheMode;

    boolean                                 palletRundingPolicyExists  = false;
    ItemId                                  itemId;

    boolean                                 searchAgain;
    CustParameters                          custParameters;

    ListEnumerator  palletRoundingPolicyItemCodeTypeEnumerator;
    ListEnumerator  palletRoundingPolicyPartyCodeTypeEnumerator;

    boolean         continueSearch = true, continueSearchSite = true;

    InventSiteId       inventSiteId;
    EcoResProductCategory productCategory;

    //Following variables are required during Rounding Threshold check.
    //Even when the certain policy is identified dring the search but does not pass the threshold rounding percentage, search should fallback and continue finding for the Layer type
    SalesQty salesQtySum;
    SalesUnit salesUnit;
    InventDimId inventDimId;

    METInventItemOrderSetup metInventItemOrderSetup;
    METPalletRoundingPolicySearchResultantHelper metPalletRoundingPolicySearchResultantHelper;

}

Method.Source:
/// <summary>
/// Method to retrieve the cache scope
/// </summary>
/// <returns>The cache scope string</returns>
public static str retrieveCacheScope()
{
    return CacheScopeFindPalletRoundingPolicy;
}

/// <summary>
/// Construct
/// </summary>
/// <param name = "_custAccount">Sales order line customer account to search pallet rounding policy from</param>
/// <param name = "_inventSiteId">Sales order line site to search pallet rounding policy from</param>
/// <param name = "_itemId">Sales order line item number to search pallet rounding policy from</param>
/// <returns>New instance of <c>METPalletRoundingPolicySearch</c></returns>
public static METPalletRoundingPolicySearch construct(CustAccount _custAccount, InventSiteId _inventSiteId, ItemId _itemId, SalesUnit _salesUnit, SalesQty _salesQtySum, InventDimId  _inventDimId)
{
    METPalletRoundingPolicySearchParameters searchParameters = METPalletRoundingPolicySearchParameters::construct();
    searchParameters.parmCustAccount(_custAccount);
    searchParameters.parmInventSiteId(_inventSiteId);
    searchParameters.parmItemId(_itemId);

    searchParameters.parmSalesUnit(_salesUnit);
    searchParameters.parmSalesQtySum(_salesQtySum);
    searchParameters.parmInventDimId(_inventDimId);

    METPalletRoundingPolicySearch palletRoundingPolicySearch = METPalletRoundingPolicySearch::newFromParameters(searchParameters);
    return palletRoundingPolicySearch;
}

/// <summary>
/// Creates a new instance of <c>METPalletRoundingPolicySearch</c> class from the parameters.
/// </summary>
/// <param name = "_searchParameters">The parameters for pallet rounding policy search.</param>
/// <returns>An instance of the pallet rounding policy search class.</returns>
protected static METPalletRoundingPolicySearch newFromParameters(METPalletRoundingPolicySearchParameters _searchParameters)
{
    METPalletRoundingPolicySearch palletRoundingPolicySearch;

    palletRoundingPolicySearch = new METPalletRoundingPolicySearch();

    palletRoundingPolicySearch.palletRoundingPolicySearchParameters = _searchParameters;

    palletRoundingPolicySearch.initialize();

    return palletRoundingPolicySearch;
}

/// <summary>
/// Initialize class variables
/// </summary>
protected void initialize()
{
    custOperGroupId = CustTable::find(palletRoundingPolicySearchParameters.parmCustAccount()).METCustOperGroupId;
    custParameters = CustParameters::find();
    itemId = palletRoundingPolicySearchParameters.parmItemId();
    inventSiteId = palletRoundingPolicySearchParameters.parmInventSiteId();
    productCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(itemId, EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::Retail).NamedCategoryHierarchyRole);

    salesUnit = palletRoundingPolicySearchParameters.parmSalesUnit();
    salesQtySum = palletRoundingPolicySearchParameters.parmSalesQtySum();
    inventDimId = palletRoundingPolicySearchParameters.parmInventDimId();

    metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(itemId, inventSiteId);
    if (!metInventItemOrderSetup)
    {
        throw Error(strFmt("@MET:PalletRoundingInventItemOrderSetupError", itemId, inventSiteId));
    }

    metPalletRoundingPolicySearchResultantHelper = METPalletRoundingPolicySearchResultantHelper::construct();
}

/// <summary>
/// Determines whether to continue pallet rounding policy search.
/// </summary>
/// <param name = "_palletRoundingPolicyPartyCodeTypeEnumerator">
/// A party code type enumerator.</param>
/// <param name = "_continueSearch">
/// A Boolean value that indicates whether to continue the pallet rounding policy search.
/// </param>
/// <returns>
/// true if needs to continue pallet rounding policy search; otherwise, false.
/// </returns>
protected boolean mustContinueSearch(ListEnumerator _palletRoundingPolicyPartyCodeTypeEnumerator, boolean _continueSearch)
{
    return _palletRoundingPolicyPartyCodeTypeEnumerator.moveNext() && _continueSearch;
}

/// <summary>
/// Searches for the pallet rounding policy and returns the pallet rounding policy record.
/// </summary>
/// <returns>METPalletRoundingPolicyLine if a pallet rounding policy record was found; otherwise, false.</returns>
public METPalletRoundingPolicySearchResultantHelper search()
{
    METCustomerGroupAll                 accountCode;
    InventCustVendRel                   accountRelation;
    METItemTableGroup                   itemCode;
    EcoResCategoryName                  itemRelation; // cater for both item number and product category name
    int iteration = 0;

    RefRecId        palletRoundingPolicyLineRefRecId;

    METPalletRoundingPolicyTypeOrderedList palletRoundingPolicyTypeOrderedList = METPalletRoundingPolicyTypeOrderedList::newFromOrder(SortOrder::Ascending);

    ListEnumerator policyTypeEnumerator = palletRoundingPolicyTypeOrderedList.getEnumerator();
    continueSearch = true;

    while (policyTypeEnumerator.moveNext() && continueSearch)
    {
        METRoundingPolicyType currentPolicyType = policyTypeEnumerator.current();

        METPalletRoundingPolicyItemCodeTypeOrderedList  palletRoundingPolicyItemCodeTypeOrderedList  = METPalletRoundingPolicyItemCodeTypeOrderedList::newFromOrder(SortOrder::Ascending);
        METPalletRoundingPolicyPartyCodeTypeOrderedList palletRoundingPolicyPartyCodeTypeOrderedList = METPalletRoundingPolicyPartyCodeTypeOrderedList::newFromOrder(false, SortOrder::Ascending);

        palletRoundingPolicyItemCodeTypeEnumerator  = palletRoundingPolicyItemCodeTypeOrderedList.getEnumerator();
        palletRoundingPolicyPartyCodeTypeEnumerator = palletRoundingPolicyPartyCodeTypeOrderedList.getEnumerator();

        continueSearchSite = true;
        palletRoundingPolicyLine = null;
        iteration = 0;

        // Loop through pallet rounding item specification Table > Table > Group > Group > Table > Group
        while (palletRoundingPolicyItemCodeTypeEnumerator.moveNext() && continueSearch)
        {
            itemCode        = palletRoundingPolicyItemCodeTypeEnumerator.current();
            itemRelation    = this.itemRelation(itemCode);
            continueSearchSite = true;

            iteration++;

            // For each of the pallet rounding party code type Table > Group > Table > Group > All > All
            while (this.mustContinueSearch(palletRoundingPolicyPartyCodeTypeEnumerator, continueSearch && continueSearchSite))
            {
                accountCode = palletRoundingPolicyPartyCodeTypeEnumerator.current();
                accountRelation = this.accountRelation(accountCode, custOperGroupId);

                if (this.validatePartyRelation(accountCode, accountRelation) 
                    && this.validateItemRelation(itemCode, itemRelation))
                {
                    // To avoid flooding the cache the most granulated setup isn't cached.
                    cacheMode = (itemCode != METItemTableGroup::Table || accountCode != METCustomerGroupAll::Table);

                    cacheValue = conNull();

                    container key;

                    if (cacheMode)
                    {
                        METPalletRoundingPolicyCacheKey cacheKey = METPalletRoundingPolicyCacheKey::construct();

                        // Initialize the cacheKey
                        cacheKey.initialize(inventSiteId, accountCode, accountRelation, itemCode, itemRelation, currentPolicyType);
                        key = cacheKey.pack();

                        cacheValue = METPalletRoundingPolicyCacheKey::getPalletRoundingPolicyCacheValue(CacheScopeFindPalletRoundingPolicy, key);
                    }

                    METPalletRoundingPercentage roundingPercentage;

                    palletRoundingPolicyLineRefRecId = 0;
                    searchAgain = false;

                    if (cacheValue == conNull())
                    {
                        Query query = this.buildFindPalletRoundingPolicyQuery(inventSiteId, accountCode, accountRelation, itemCode, itemRelation, currentPolicyType);

                        QueryRun queryRun = new QueryRun(query);

                        while (queryRun.next())
                        {
                            palletRoundingPolicyLine = queryRun.get(tableNum(METPalletRoundingPolicyLine));

                            // For product category
                            if (itemCode == METItemTableGroup::GroupId)
                            {
                                boolean isDescendant = EcoResCategory::isDescendant(productCategory.Category, palletRoundingPolicyLine.Category, true);
                                // if the current item category is not a descendant of the pallet rounding policy line category, go to the next line category
                                if (!isDescendant)
                                {
                                    continue;
                                }
                            }

                            if (cacheMode)
                            {
                                cacheValue += [[palletRoundingPolicyLine.RoundingPercentage, 
                                    palletRoundingPolicyLine.RecId]];

                                // in case multiple policies with item category
                                break;
                            }
                            else
                            {
                                palletRoundingPolicyLineRefRecId = palletRoundingPolicyLine.RecId;

                                // Method to check if valid METPalletRoundingPolicyLine
                                // Giving _palletRoundingPolicyLineRefRecId 0 as a parameter to avoid reselecting palletRoundingPolicyLine from above
                                continueSearch = this.continueSearch(palletRoundingPolicyLine);
                                if (!continueSearch)
                                {
                                    break;
                                }

                            }
                        }

                        if (cacheMode)
                        {
                            //We also want to cache the absence of pallet rounding policy.
                            if (cacheValue == conNull())
                            {
                                cacheValue = [[0]];
                            }

                            // add cacheValue against the key in the cache
                            METPalletRoundingPolicyCacheKey::insertPalletRoundingPolicyCache(CacheScopeFindPalletRoundingPolicy, key, cacheValue);
                        }
                    }

                    if (cacheMode && cacheValue)
                    {
                        for (int i=1; i<=conLen(cacheValue); i++)
                        {
                            [roundingPercentage, palletRoundingPolicyLineRefRecId] = conPeek(cacheValue, i);

                            if (palletRoundingPolicyLineRefRecId)
                            {
                                palletRoundingPolicyLine = METPalletRoundingPolicyLine::findRecId(palletRoundingPolicyLineRefRecId);

                                if (palletRoundingPolicyLine)
                                {
                                    continueSearch = this.continueSearch(palletRoundingPolicyLine);
                                    if (!continueSearch)
                                    {
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            palletRoundingPolicyPartyCodeTypeEnumerator.reset();

            if (iteration == 2)
            {
                palletRoundingPolicyItemCodeTypeEnumerator.reset();

                // For priority 5 and 6 customer specification becomes All customers
                palletRoundingPolicyPartyCodeTypeOrderedList = METPalletRoundingPolicyPartyCodeTypeOrderedList::newFromOrder(true, SortOrder::Ascending);
                palletRoundingPolicyPartyCodeTypeEnumerator = palletRoundingPolicyPartyCodeTypeOrderedList.getEnumerator();
            }
        }
    }

    metPalletRoundingPolicySearchResultantHelper.parmMETPalletRoundingPolicyLine(palletRoundingPolicyLine);
    return metPalletRoundingPolicySearchResultantHelper;
}

/// <summary>
/// Specifies the item relation for a given <c>METItemTableGroup</c> during finding the pallet rounding policy.
/// </summary>
/// <param name = "_itemCode">The item code type to specify the item relation for.</param>
/// <returns>Returns item number or product category record id to find the pallet rounding policy for.</returns>
/// <remarks>We are only managing specific item or item categories.</remarks>
protected EcoResCategoryName itemRelation(METItemTableGroup    _itemCode)
{
    switch (_itemCode)
    {
        case METItemTableGroup::Table:
            return itemId;
        case METItemTableGroup::GroupId:
            return int642Str(EcoResCategory::find(productCategory.Category).RecId);
        default:
            return '';
    }
}

/// <summary>
/// Returns the account relation for a given <c>METCustomerGroupAll</c> during finding the pallet rounding policy.
/// </summary>
/// <param name = "_accountCode">The party code type to return the account number for.</param>
/// <param name = "_groupId">The customer operations group Id.</param>
/// <returns>Returns the account relation to to find the pallet rounding policy for.</returns>
protected CustVendAC accountRelation(METCustomerGroupAll    _accountCode,
                                     METCustOperGroupId     _groupId)
{
    switch (_accountCode)
    {
        case METCustomerGroupAll::Table:
            return palletRoundingPolicySearchParameters.parmCustAccount();
        case METCustomerGroupAll::GroupId:
            return _groupId;
        default:
            return '';
    }
}

/// <summary>
/// Validate party relation
/// </summary>
/// <param name = "_code">Customer account code type</param>
/// <param name = "_relation">account relation</param>
/// <returns>true if validation successful; otherwise, false.</returns>
public boolean validatePartyRelation(METCustomerGroupAll _code, str _relation)
{
    boolean  ok = true;

    if (_relation && _code == METCustomerGroupAll::All)
    {
        ok = false;
    }

    if (!_relation && _code != METCustomerGroupAll::All)
    {
        ok = false;
    }

    return ok;
}

/// <summary>
/// Validate item relation
/// </summary>
/// <param name = "_code">Item code type</param>
/// <param name = "_relation">item relation</param>
/// <returns>true if validation successful; otherwise, false.</returns>
public boolean validateItemRelation(METItemTableGroup _code, str _relation)
{
    boolean  ok = true;

    if (!_relation)
    {
        ok = false;
    }

    return ok;
}

/// <summary>
/// Builds the query for finding policy rounding policy based on the parameters.
/// </summary>
/// <param name = "_siteId">The <c>InventSiteId</c> value.</param>
/// <param name = "_accountCode">The account code.</param>
/// <param name = "_accountRel">The customer or customer operations group id.</param>
/// <param name = "_itemCode">The item code.</param>
/// <param name = "_itemRel">Item number or prodcut categorie.</param>
/// <param name = "_policyType">Rounding policy type, could be Pallet or Layer</param>
/// <returns>A <c>Query</c> object.</returns>
protected Query buildFindPalletRoundingPolicyQuery(InventSiteId                        _siteId,
                                                   METCustomerGroupAll                 _accountCode,
                                                   InventCustVendRel                   _accountRel,
                                                   METItemTableGroup                   _itemCode,
                                                   EcoResCategoryName                  _itemRel,
                                                   METRoundingPolicyType               _policyType)
{
    Query query = new Query();

    QueryBuildDataSource qbds = query.addDataSource(tableNum(METPalletRoundingPolicyLine));

    qbds.addRange(fieldNum(METPalletRoundingPolicyLine, InventSiteId)).value(queryValue(_siteId));
    qbds.addRange(fieldNum(METPalletRoundingPolicyLine, AccountCode)).value(queryValue(_accountCode));
    qbds.addRange(fieldNum(METPalletRoundingPolicyLine, AccountRelation)).value(queryValue(_accountRel));
    qbds.addRange(fieldNum(METPalletRoundingPolicyLine, ItemCode)).value(queryValue(_itemCode));
    qbds.addRange(fieldNum(METPalletRoundingPolicyLine, PolicyType)).value(queryValue(_policyType));

    // For table, we filter using the item id. 
    // For category, as there is a hierarchy, we will validate the current item category is a descendant of ItemRelation
    if (_itemCode == METItemTableGroup::Table)
    {
        qbds.addRange(fieldNum(METPalletRoundingPolicyLine, ItemId)).value(queryValue(_itemRel));
    }

    QueryBuildDataSource headerQbds = qbds.addDataSource(tableNum(METPalletRoundingPolicyHeader));
    headerQbds.relations(true);
    headerQbds.joinMode(JoinMode::ExistsJoin);
    headerQbds.addRange(fieldNum(METPalletRoundingPolicyHeader, Active)).value(queryValue(NoYes::Yes));

    return query;
}

/// <summary>
/// This method is used to compare the calculated percentage with the rounding percentage of the searched rounding record.
/// </summary>
/// <param name = "_palletRoundingPolicyLine">Unique rounding record buffer</param>
/// <param name = "_salesQtySum">Summend sales line quanties grouped by customer, Item, site</param>
/// <param name = "_salesUnit">Unit on the sales line selected</param>
/// <param name = "_inventDimId">Unique invntory dimension record</param>
/// <returns>Boolean true,if comparison is successful, else false</returns>
private boolean isRoundingThresholdSatisfied(METPalletRoundingPolicyLine _palletRoundingPolicyLine, Qty _salesQtySum, UnitOfMeasureSymbol _salesUnit, InventDimId _inventDimId)
{
    boolean isRoundingThresholdSatisfied ;
    Qty baseQty; // a PalletQty or PalletLayerQty based on PolicyType.
    InventQty salesLineInventQty;
    UnitOfMeasureSymbol inventUnitId = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent).UnitId;

    salesLineInventQty = EcoResProductUnitConverter::convertForReleasedProduct( this.ItemId,
                                                                               _inventDimId,
                                                                               _salesQtySum,
                                                                               UnitOfMeasure::unitOfMeasureIdBySymbol(_salesUnit),
                                                                               UnitOfMeasure::unitOfMeasureIdBySymbol(inventUnitId));

    if (_palletRoundingPolicyLine.PolicyType == METRoundingPolicyType::Pallet)
    {
        baseQty = metInventItemOrderSetup.PalletQty;
    }
    else if (_palletRoundingPolicyLine.PolicyType == METRoundingPolicyType::Layer)
    {
        baseQty = metInventItemOrderSetup.PalletLayerQty;
    }

    if (baseQty == 0)
    {
        return false;
    }

    InventQty modQty = salesLineInventQty mod baseQty;

    real roundingPercentage = (modQty * 100.0) / baseQty;

    if(roundingPercentage >= _palletRoundingPolicyLine.RoundingPercentage)
    {
        isRoundingThresholdSatisfied = true;

        // To update sales order line fields
        // If above checks are successful, apply the pallet rounding.
        // Convert the new quantity from the item's inventory unit of measure to the sales order unit of measure and apply it to the original sales order line (not on the bonus stock line).
        InventQty salesLineRoundedInventQty = salesLineInventQty + baseQty - modQty;
        InventQty salesLineDiffInventQty = salesLineRoundedInventQty - salesLineInventQty;

        SalesQty salesLineRoundedSalesQty = EcoResProductUnitConverter::convertForReleasedProduct(this.ItemId,
                                                                                   this.inventDimId,
                                                                                   salesLineDiffInventQty,
                                                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(inventUnitId),
                                                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(salesUnit));

        metPalletRoundingPolicySearchResultantHelper.parmSalesLineRoundedSalesQty(salesLineRoundedSalesQty);
    }

    return isRoundingThresholdSatisfied;
}

/// <summary>
/// Method to determine if search has to continue even as when suitable pallet rounding record is determined and being validated.
/// </summary>
/// <param name = "_palletRoundingPolicyLine">Unique rounding record buffer</param>
/// <returns>Bollean true, if search as to continue. else false</returns>
protected boolean continueSearch(METPalletRoundingPolicyLine _palletRoundingPolicyLine)
{
    boolean shouldContinueSearch = true;
    boolean isValidationSuccessfull = this.validate(_palletRoundingPolicyLine);

    if (isValidationSuccessfull)
    {
        if(this.isRoundingThresholdSatisfied(_palletRoundingPolicyLine, salesQtySum, salesUnit, inventDimId))
        {
            shouldContinueSearch = false;
        }
    }
    else
    {
        // Found record from the search, but did not pass the validation.
        // Hence not checking rounding threshold and should not continue to search.Setting ret as false
        shouldContinueSearch = false;
    }

    return shouldContinueSearch;
}

/// <summary>
/// Validate before rounding policy is applied.
/// </summary>
/// <param name = "_palletRoundingPolicyLine">METPalletRoundingPolicyLine buffer</param>
/// <returns>True if validation successful; otherwise, false</returns>
protected boolean validate(METPalletRoundingPolicyLine _palletRoundingPolicyLine)
{
    boolean ret = true;

    if (!metInventItemOrderSetup)
    {
        throw Error(strFmt("@MET:PalletRoundingInventItemOrderSetupError", itemId, inventSiteId));
    }

    boolean checkDefaultOrderSettings(FieldId _fieldId)
    {
        if (!metInventItemOrderSetup.(_fieldId))
        {
            ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupPalletQtyError", fieldId2PName(metInventItemOrderSetup.TableId, _fieldId), itemId, inventSiteId));
        }
        return ret;
    }

    if (_palletRoundingPolicyLine.PolicyType == METRoundingPolicyType::Pallet)
    {
        checkDefaultOrderSettings(fieldNum(METInventItemOrderSetup, PalletQty));
        checkDefaultOrderSettings(fieldNum(METInventItemOrderSetup, CartonPerPallet));
    }
    else if (_palletRoundingPolicyLine.PolicyType == METRoundingPolicyType::Layer)
    {
        checkDefaultOrderSettings(fieldNum(METInventItemOrderSetup, PalletLayerQty));
        checkDefaultOrderSettings(fieldNum(METInventItemOrderSetup, CartonPerLayer));
    }

    if (!ret)
    {
        throw Error("@SYS326740");
    }

    return metPalletRoundingPolicySearchResultantHelper.parmHasInventOrderSetup(ret);
}
